import os
from azure.storage.blob import BlobServiceClient

class AzureStorageClient:
    def __init__(self):
        self.connection_string = os.environ.get("AZURE_STORAGE_CONNECTION_STRING")
        if not self.connection_string:
            raise ValueError("AZURE_STORAGE_CONNECTION_STRING environment variable not set.")
        self.blob_service_client = BlobServiceClient.from_connection_string(self.connection_string)

    def get_blob_client(self, container_name: str, blob_name: str):
        container_client = self.blob_service_client.get_container_client(container_name)
        return container_client.get_blob_client(blob_name)

    def get_container_client(self, container_name: str):
        return self.blob_service_client.get_container_client(container_name)

import os
from storage_client import AzureStorageClient
from storage_models import UploadObjectRequest, UploadObjectResponse

def upload_object(request: UploadObjectRequest) -> UploadObjectResponse:
    try:
        storage_client = AzureStorageClient()
        blob_client = storage_client.get_blob_client(request.container_name, request.blob_name)

        if request.file_path:
            with open(request.file_path, "rb") as data:
                blob_client.upload_blob(data, metadata=request.metadata, overwrite=True)
        elif request.data is not None:
            blob_client.upload_blob(request.data, metadata=request.metadata, overwrite=True)
        else:
            return UploadObjectResponse(success=False, error="Either file_path or data must be provided.")

        return UploadObjectResponse(success=True, blob_url=blob_client.url)
    except Exception as e:
        return UploadObjectResponse(success=False, error=str(e))

from storage_client import AzureStorageClient
from storage_models import ObjectMetadataRequest, ObjectMetadataResponse

def get_object_metadata(request: ObjectMetadataRequest) -> ObjectMetadataResponse:
    try:
        storage_client = AzureStorageClient()
        blob_client = storage_client.get_blob_client(request.container_name, request.blob_name)
        properties = blob_client.get_blob_properties()

        metadata = properties.metadata
        size = properties.size
        last_modified = properties.last_modified.isoformat() if properties.last_modified else None

        return ObjectMetadataResponse(
            success=True,
            metadata=metadata,
            size=size,
            last_modified=last_modified
        )
    except Exception as e:
        return ObjectMetadataResponse(success=False, error=str(e))

from storage_client import AzureStorageClient
from storage_models import ListPrefixRequest, ListPrefixResponse, ListedObject

def list_prefix(request: ListPrefixRequest) -> ListPrefixResponse:
    try:
        storage_client = AzureStorageClient()
        container_client = storage_client.get_container_client(request.container_name)

        blob_list = []
        for blob in container_client.list_blobs(name_starts_with=request.prefix):
            blob_list.append(ListedObject(
                name=blob.name,
                size=blob.size,
                last_modified=blob.last_modified.isoformat() if blob.last_modified else None
            ))

        return ListPrefixResponse(success=True, objects=blob_list)
    except Exception as e:
        return ListPrefixResponse(success=False, error=str(e))

import os
from azure.ai.formrecognizer import DocumentAnalysisClient
from azure.core.credentials import AzureKeyCredential
from storage_client import AzureStorageClient
from storage_models import StoredDocumentOcrRequest, StoredDocumentOcrResponse

def stored_document_ocr(request: StoredDocumentOcrRequest) -> StoredDocumentOcrResponse:
    try:
        endpoint = os.environ.get("AZURE_VISION_ENDPOINT")
        key = os.environ.get("AZURE_VISION_KEY")

        if not endpoint or not key:
            return StoredDocumentOcrResponse(success=False, error="AZURE_VISION_ENDPOINT and AZURE_VISION_KEY environment variables must be set.")

        storage_client = AzureStorageClient()
        blob_client = storage_client.get_blob_client(request.container_name, request.blob_name)
        blob_url = blob_client.url

        document_analysis_client = DocumentAnalysisClient(
            endpoint=endpoint, credential=AzureKeyCredential(key)
        )

        poller = document_analysis_client.begin_analyze_document_from_url(
            "prebuilt-read", blob_url
        )
        result = poller.result()

        extracted_text = "\n".join([page.content for page in result.pages])

        return StoredDocumentOcrResponse(success=True, extracted_text=extracted_text)
    except Exception as e:
        return StoredDocumentOcrResponse(success=False, error=str(e))

import os
import requests
import uuid
import json
from storage_models import StoredTextTranslateRequest, StoredTextTranslateResponse

def stored_text_translate(request: StoredTextTranslateRequest) -> StoredTextTranslateResponse:
    try:
        endpoint = os.environ.get("AZURE_TRANSLATOR_ENDPOINT")
        key = os.environ.get("AZURE_TRANSLATOR_KEY")
        region = os.environ.get("AZURE_TRANSLATOR_REGION") # e.g., eastus

        if not endpoint or not key or not region:
            return StoredTextTranslateResponse(success=False, error="AZURE_TRANSLATOR_ENDPOINT, AZURE_TRANSLATOR_KEY, and AZURE_TRANSLATOR_REGION environment variables must be set.")

        path = '/translate'
        constructed_url = endpoint + path

        params = {
            'api-version': '3.0',
            'to': request.target_language
        }
        if request.source_language:
            params['from'] = request.source_language

        headers = {
            'Ocp-Apim-Subscription-Key': key,
            'Ocp-Apim-Subscription-Region': region,
            'Content-type': 'application/json',
            'X-ClientTraceId': str(uuid.uuid4())
        }

        body = [{'text': request.text}]

        r = requests.post(constructed_url, params=params, headers=headers, json=body)
        response_data = r.json()

        if r.status_code == 200 and response_data and len(response_data) > 0 and 'translations' in response_data[0] and len(response_data[0]['translations']) > 0:
            translated_text = response_data[0]['translations'][0]['text']
            return StoredTextTranslateResponse(success=True, translated_text=translated_text)
        else:
            return StoredTextTranslateResponse(success=False, error=f"Translation failed: {response_data}")

    except Exception as e:
        return StoredTextTranslateResponse(success=False, error=str(e))

import os
from openai import AzureOpenAI
from storage_models import StoredAssetSummaryRequest, StoredAssetSummaryResponse

def stored_asset_summary(request: StoredAssetSummaryRequest) -> StoredAssetSummaryResponse:
    try:
        azure_openai_endpoint = os.environ.get("AZURE_OPENAI_ENDPOINT")
        azure_openai_key = os.environ.get("AZURE_OPENAI_KEY")
        azure_openai_deployment_name = os.environ.get("AZURE_OPENAI_DEPLOYMENT_NAME", "text-davinci-003") # Example deployment name

        if not azure_openai_endpoint or not azure_openai_key:
            return StoredAssetSummaryResponse(success=False, error="AZURE_OPENAI_ENDPOINT and AZURE_OPENAI_KEY environment variables must be set.")

        client = AzureOpenAI(
            azure_endpoint=azure_openai_endpoint,
            api_key=azure_openai_key,
            api_version="2023-05-15"
        )

        prompt = f"Summarize the following text, aiming for a {request.summary_length} summary: {request.text}"

        response = client.completions.create(
            model=azure_openai_deployment_name,
            prompt=prompt,
            max_tokens=150 if request.summary_length == "short" else (300 if request.summary_length == "medium" else 500),
            temperature=0.7
        )

        summary = response.choices[0].text.strip()
        return StoredAssetSummaryResponse(success=True, summary=summary)
    except Exception as e:
        return StoredAssetSummaryResponse(success=False, error=str(e))

import os
from openai import AzureOpenAI
from storage_models import AssetMetadataEmbeddingRequest, AssetMetadataEmbeddingResponse

def asset_metadata_embedding(request: AssetMetadataEmbeddingRequest) -> AssetMetadataEmbeddingResponse:
    try:
        azure_openai_endpoint = os.environ.get("AZURE_OPENAI_ENDPOINT")
        azure_openai_key = os.environ.get("AZURE_OPENAI_KEY")
        azure_openai_embedding_deployment_name = os.environ.get("AZURE_OPENAI_EMBEDDING_DEPLOYMENT_NAME", "text-embedding-ada-002") # Example deployment name

        if not azure_openai_endpoint or not azure_openai_key:
            return AssetMetadataEmbeddingResponse(success=False, error="AZURE_OPENAI_ENDPOINT and AZURE_OPENAI_KEY environment variables must be set.")

        client = AzureOpenAI(
            azure_endpoint=azure_openai_endpoint,
            api_key=azure_openai_key,
            api_version="2023-05-15"
        )

        text_to_embed = request.text_content
        if request.metadata_tags:
            metadata_string = ", ".join([f"{k}: {v}" for k, v in request.metadata_tags.items()])
            text_to_embed = f"{text_to_embed}\nMetadata: {metadata_string}"

        response = client.embeddings.create(
            model=azure_openai_embedding_deployment_name,
            input=text_to_embed
        )

        embedding = response.data[0].embedding
        return AssetMetadataEmbeddingResponse(success=True, embedding=embedding)
    except Exception as e:
        return AssetMetadataEmbeddingResponse(success=False, error=str(e))
